    opacity: 0;
    transform: translate(
      calc(var(--x) + var(--drift)),
      calc(var(--y) + 120px)
    ) rotate(var(--spin)) scale(0.4);
  }
}

@utility animate-confetti {
  position: absolute;
  width: 8px;
  height: 8px;
  will-change: transform, opacity;
  animation: confetti-fall 1.2s cubic-bezier(0, 0.9, 0.57, 1) forwards;
  pointer-events: none;
}

"use client";

import { useEffect, useRef, type MouseEvent, type ReactNode } from "react";

const COLORS = ["#ff006e", "#fb5607", "#ffbe0b", "#8338ec", "#3a86ff", "#06d6a0"];
const PARTICLE_COUNT = 26;

type AnimeModule = typeof import("animejs");
type AnimeAnimation = {
  cancel(): unknown;
};

function prefersReducedMotion() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export function ConfettiButton({ children }: { children: ReactNode }) {
  const buttonRef = useRef<HTMLButtonElement>(null);
  const animeRef = useRef<Promise<AnimeModule> | null>(null);
  const activeParticlesRef = useRef<Array<{ animation: AnimeAnimation; element: HTMLSpanElement }>>([]);

  useEffect(() => {
    return () => {
      activeParticlesRef.current.forEach(({ animation, element }) => {
        animation.cancel();
        element.remove();
      });
      activeParticlesRef.current = [];
    };
  }, []);

  function getAnime() {
    animeRef.current ??= import("animejs");
    return animeRef.current;
  }

  function createParticle(button: HTMLButtonElement, x: number, y: number, index: number) {
    const particle = document.createElement("span");
    particle.className = "pointer-events-none absolute block will-change-transform";
    Object.assign(particle.style, {
      background: COLORS[index % COLORS.length],
      borderRadius: Math.random() > 0.45 ? "50%" : "1px",
      height: "8px",
      left: x - 4 + "px",
      top: y - 4 + "px",
      width: "8px",
    });
    button.appendChild(particle);
    return particle;
  }

  function removeParticle(particle: HTMLSpanElement) {
    activeParticlesRef.current = activeParticlesRef.current.filter(
      (entry) => entry.element !== particle
    );
    particle.remove();
  }

  async function handleClick(event: MouseEvent<HTMLButtonElement>) {
    const button = event.currentTarget;
    const rect = button.getBoundingClientRect();
    const originX = event.clientX - rect.left;
    const originY = event.clientY - rect.top;
    if (prefersReducedMotion()) return;

    const { animate } = await getAnime();
    if (buttonRef.current !== button) return;

    animate(button, { scale: [0.97, 1], duration: 220, ease: "out(3)" });

    Array.from({ length: PARTICLE_COUNT }, (_, index) => {
      const angle = (Math.PI * 2 * index) / PARTICLE_COUNT + (Math.random() - 0.5) * 0.5;
      const velocity = 58 + Math.random() * 90;
      const particle = createParticle(button, originX, originY, index);
      const animation = animate(particle, {
        x: [0, Math.cos(angle) * velocity],
        y: [0, Math.sin(angle) * velocity + 104],
        rotate: ["0deg", Math.random() * 720 - 360 + "deg"],
        scale: [1, 0.35],
        opacity: [1, 0],
        duration: 1050 + Math.random() * 220,
        delay: index * 5,
        ease: "out(3)",
        onComplete: () => removeParticle(particle),
      });
      activeParticlesRef.current.push({ animation, element: particle });
    });
  }

  return (
    <button
      ref={buttonRef}
      onClick={handleClick}
      className="relative overflow-visible px-6 py-3 bg-zinc-900 text-white"
    >
      {children}
    </button>
  );
}

"use client";

import { motion, AnimatePresence } from "framer-motion";
import { useState, type MouseEvent } from "react";

const COLORS = ["#ff006e", "#fb5607", "#ffbe0b", "#8338ec", "#3a86ff", "#06d6a0"];

interface Particle {
  id: number;
  x: number;
  y: number;
  color: string;
  angle: number;
  velocity: number;
}

function spawnParticles(x: number, y: number, count = 20): Particle[] {
  return Array.from({ length: count }, (_, i) => ({
    id: Date.now() + i,
    x,
    y,
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
    angle: (Math.PI * 2 * i) / count + (Math.random() - 0.5) * 0.5,
    velocity: 60 + Math.random() * 80,
  }));
}

export function ConfettiButton({ children }: { children: React.ReactNode }) {
  const [particles, setParticles] = useState<Particle[]>([]);

  function handleClick(e: MouseEvent<HTMLButtonElement>) {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setParticles((prev) => [...prev, ...spawnParticles(x, y)]);
  }

  return (
    <button onClick={handleClick} style={{ position: "relative", overflow: "visible" }}>
      {children}
      <AnimatePresence>
        {particles.map((p) => (
          <motion.span
            key={p.id}
            initial={{
              x: p.x,
              y: p.y,
              scale: 1,
              opacity: 1,
            }}
            animate={{
              x: p.x + Math.cos(p.angle) * p.velocity,
              y: p.y + Math.sin(p.angle) * p.velocity + 120,
              scale: 0.4,
              opacity: 0,
              rotate: Math.random() * 720 - 360,
            }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1.2, ease: [0, 0.9, 0.57, 1] }}
            onAnimationComplete={() =>
              setParticles((prev) => prev.filter((pp) => pp.id !== p.id))
            }
            style={{
              position: "absolute",
              width: 8,
              height: 8,
              borderRadius: Math.random() > 0.5 ? "50%" : "1px",
              background: p.color,
              pointerEvents: "none",
            }}
          />
        ))}
      </AnimatePresence>
    </button>
  );
}

/* === Scroll Page Turn ===
 * Each .page-turn-section is a sticky full-screen panel.
 * Wrap them inside a tall scroll container so the user's
 * scroll progress drives the 3D rotation via JS or
 * scroll-timeline (where supported).
 */

.page-turn-container {
  perspective: 1200px;
  perspective-origin: center center;
}

.page-turn-section {
  position: sticky;
  top: 0;
  width: 100%;
  height: 100vh;
  overflow: hidden;
  transform-origin: left center;
  will-change: transform, opacity;
  backface-visibility: hidden;
  transition: transform 0.1s linear, opacity 0.1s linear;
}

/* Shadow on the folding edge — driven by the same scroll progress */
.page-turn-section::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    to left,
    rgba(0, 0, 0, 0.4) 0%,
    transparent 60%
  );
  opacity: 0;
  transition: opacity 0.1s linear;
}

/* When the page is mid-turn, show the fold shadow */
.page-turn-section[data-turning="true"]::after {
  opacity: 1;
}

/* Reduced motion: instant cut, no 3D */
@media (prefers-reduced-motion: reduce) {
  .page-turn-section {
    transform: none !important;
    transition: none;
  }
  .page-turn-section::after {
    display: none;
  }
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";

/**
 * Hook: maps scroll progress of a tall wrapper to 0-1.
 * Each "page" occupies 100vh of scroll distance.
 */
function useScrollProgress() {
  const containerRef = useRef<HTMLDivElement>(null);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    function onScroll() {
      const rect = el!.getBoundingClientRect();
      const scrollable = el!.scrollHeight - window.innerHeight;
      const scrolled = -rect.top;
      setProgress(Math.max(0, Math.min(1, scrolled / scrollable)));
    }

    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return { containerRef, progress };
}

interface PageTurnProps {
  pages: ReactNode[];
  className?: string;
}

export function PageTurn({ pages, className }: PageTurnProps) {
  const { containerRef, progress } = useScrollProgress();
  const total = pages.length;

  // Height: each page gets 100vh of scroll room
  const containerHeight = `${total * 100}vh`;

  return (
    <div
      ref={containerRef}
      className={className}
      style={{ height: containerHeight, position: "relative" }}
    >
      <div
        className="sticky top-0 h-screen w-full"
        style={{ perspective: "1200px" }}
      >
        {pages.map((page, i) => {
          // Each page turns between progress i/(total-1) and (i+1)/(total-1)
          const start = i / total;
          const end = (i + 1) / total;
          const local = Math.max(
            0,
            Math.min(1, (progress - start) / (end - start))
          );
          const angle = local * -90;
          const opacity = 1 - local;
          const shadow = local * 0.5;

          return (
            <div
              key={i}
              className="absolute inset-0"
              style={{
                transformOrigin: "left center",
                transform: `rotateY(${angle}deg)`,
                opacity: Math.max(0, opacity),
                zIndex: total - i,
                backfaceVisibility: "hidden",
                boxShadow:
                  shadow > 0
                    ? `inset -30px 0 60px rgba(0,0,0,${shadow})`
                    : "none",
              }}
            >
              {page}
            </div>
          );
        })}
      </div>
    </div>
  );
}

