  const opacity = useTransform(scrollYProgress, [0, 0.6, 1], [1, 0.8, 0]);
  const shadow = useTransform(
    scrollYProgress,
    [0, 1],
    [
      "-0px 0px 0px rgba(0,0,0,0)",
      "-12px 12px 40px rgba(0,0,0,0.35)",
    ]
  );

  return (
    <div ref={ref} style={{ height: "100vh" }}>
      <motion.div
        style={{
          position: "sticky",
          top: 0,
          height: "100vh",
          width: "100%",
          transformOrigin: "bottom left",
          rotateX,
          rotateZ,
          y,
          scale,
          opacity,
          boxShadow: shadow,
          zIndex: total - index,
        }}
      >
        {children}
      </motion.div>
    </div>
  );
